import json
import sys
import base64
import hashlib
import zipfile
import io
import datetime


def validate_request(req):
    if set(req.keys()) != {'members', 'timestamp', 'comment'}:
        return False
    if not isinstance(req['members'], list) or len(req['members']) < 1 or len(req['members']) > 64:
        return False
    for member in req['members']:
        if set(member.keys()) != {'path', 'content_b64', 'mode'}:
            return False
        path = member['path']
        if not isinstance(path, str) or path.startswith('/') or '\\' in path:
            return False
        parts = path.split('/')
        if any(p == '' or p == '.' or p == '..' for p in parts):
            return False
        content_b64 = member['content_b64']
        if not isinstance(content_b64, str):
            return False
        try:
            content = base64.b64decode(content_b64)
            if len(content) > 64 * 1024:
                return False
        except Exception:
            return False
        mode = member['mode']
        if not isinstance(mode, int) or mode < 0 or mode > 511:
            return False
    ts = req['timestamp']
    if not isinstance(ts, list) or len(ts) != 6:
        return False
    for val in ts:
        if not isinstance(val, int):
            return False
    year, month, day, hour, minute, second = ts
    if year < 1980 or year > 2107 or second % 2 != 0:
        return False
    try:
        datetime.datetime(year, month, day, hour, minute, second)
    except ValueError:
        return False
    comment = req['comment']
    if not isinstance(comment, str) or len(comment) > 200:
        return False
    return True


def create_zip(req):
    members = sorted(req['members'], key=lambda m: m['path'])
    zip_buffer = io.BytesIO()
    with zipfile.ZipFile(zip_buffer, 'w', zipfile.ZIP_DEFLATED) as zf:
        ts = req['timestamp']
        for member in members:
            content = base64.b64decode(member['content_b64'])
            info = zipfile.ZipInfo(member['path'])
            info.compress_type = zipfile.ZIP_DEFLATED
            info.date_time = (ts[0], ts[1], ts[2], ts[3], ts[4], ts[5])
            info.external_attr = (0o100000 | member['mode']) << 16
            zf.writestr(info, content)
        zf.comment = req['comment'].encode('utf-8')
    return zip_buffer.getvalue()


def main():
    try:
        req = json.loads(sys.stdin.read())
    except (json.JSONDecodeError, ValueError, TypeError):
        print(json.dumps({"error": "invalid_request"}))
        return

    if not validate_request(req):
        print(json.dumps({"error": "invalid_request"}))
        return

    try:
        archive_bytes = create_zip(req)
        archive_b64 = base64.b64encode(archive_bytes).decode('ascii')
        sha256 = hashlib.sha256(archive_bytes).hexdigest()
        result = {"format": "zip", "archive_b64": archive_b64, "sha256": sha256}
        print(json.dumps(result))
    except Exception:
        print(json.dumps({"error": "invalid_request"}))


if __name__ == '__main__':
    main()
